### 1. `Book.swift`: в модель добавляется одно поле

```swift
import Foundation
import SwiftData

@Model
final class Book {
    var id: UUID
    var title: String
    var author: String
    var addedAt: Date
    /// Ссылка на файлы обложки в CoverStore; nil — обложки нет.
    var coverID: UUID?

    init(id: UUID = UUID(), title: String, author: String, addedAt: Date = .now, coverID: UUID? = nil) {
        self.id = id
        self.title = title
        self.author = author
        self.addedAt = addedAt
        self.coverID = coverID
    }
}

extension Book {
    /// Удаляет книгу вместе с файлами обложки. Использовать вместо context.delete(book).
    @MainActor
    func deleteWithCover(from context: ModelContext) {
        let coverID = self.coverID
        context.delete(self)
        try? context.save()
        if let coverID {
            Task { await CoverStore.shared.deleteCover(coverID) }
        }
    }
}
```

### 2. `CoverStore.swift`: подготовка, хранение и загрузка обложек

```swift
import UIKit
import ImageIO
import UniformTypeIdentifiers

nonisolated enum CoverRendition: CaseIterable, Sendable {
    /// Для списка библиотеки.
    case thumbnail
    /// Для экрана книги.
    case full

    var fileSuffix: String {
        switch self {
        case .thumbnail: "thumb"
        case .full: "full"
        }
    }

    /// Длинная сторона в пикселях.
    var maxPixelSize: Int {
        switch self {
        case .thumbnail: 450
        case .full: 1500
        }
    }
}

nonisolated enum CoverError: Error {
    case renderFailed
    case encodingFailed
}

/// Хранит обложки файлами в Application Support/Covers:
/// "<coverID>-thumb" и "<coverID>-full" (HEIC, если доступен, иначе JPEG).
nonisolated final class CoverStore: Sendable {
    static let shared = CoverStore()

    private let directory: URL
    private let cache = CoverCache()

    init(directory: URL = URL.applicationSupportDirectory.appending(path: "Covers", directoryHint: .isDirectory)) {
        self.directory = directory
    }

    // MARK: Сохранение

    /// Уменьшает фото с камеры, записывает обе версии и возвращает новый coverID.
    /// Новый ID на каждую съёмку, поэтому кэш никогда не покажет старую обложку.
    @concurrent
    func saveCover(from photo: UIImage) async throws -> UUID {
        let id = UUID()
        try FileManager.default.createDirectory(at: directory, withIntermediateDirectories: true)

        let full = try Self.render(photo, maxPixelSize: CoverRendition.full.maxPixelSize)
        let thumbnail = try Self.render(UIImage(cgImage: full), maxPixelSize: CoverRendition.thumbnail.maxPixelSize)

        do {
            try Self.encode(full).write(to: fileURL(id, .full), options: .atomic)
            try Self.encode(thumbnail).write(to: fileURL(id, .thumbnail), options: .atomic)
        } catch {
            removeFiles(id)
            throw error
        }
        return id
    }

    // MARK: Загрузка

    /// Мгновенно, без диска: для первого кадра строки списка.
    func cachedImage(_ id: UUID, _ rendition: CoverRendition) -> UIImage? {
        cache.image(forKey: cacheKey(id, rendition))
    }

    /// Читает и декодирует обложку вне главного потока. nil — файла нет или задача отменена.
    @concurrent
    func loadImage(_ id: UUID, _ rendition: CoverRendition) async -> UIImage? {
        let key = cacheKey(id, rendition)
        if let cached = cache.image(forKey: key) { return cached }
        if Task.isCancelled { return nil }

        let sourceOptions = [kCGImageSourceShouldCache: false] as CFDictionary
        guard let source = CGImageSourceCreateWithURL(fileURL(id, rendition) as CFURL, sourceOptions) else {
            return nil
        }
        let options: [CFString: Any] = [
            kCGImageSourceCreateThumbnailFromImageAlways: true,
            kCGImageSourceCreateThumbnailWithTransform: true,
            // Декодировать сразу здесь, а не на главном потоке при отрисовке.
            kCGImageSourceShouldCacheImmediately: true,
            kCGImageSourceThumbnailMaxPixelSize: rendition.maxPixelSize,
        ]
        guard let cgImage = CGImageSourceCreateThumbnailAtIndex(source, 0, options as CFDictionary) else {
            return nil
        }
        let image = UIImage(cgImage: cgImage)
        cache.insert(image, forKey: key, cost: cgImage.bytesPerRow * cgImage.height)
        return image
    }

    // MARK: Удаление

    @concurrent
    func deleteCover(_ id: UUID) async {
        removeFiles(id)
    }

    /// Удаляет файлы, на которые не ссылается ни одна книга (сбой посреди сохранения,
    /// удаление книги в обход deleteWithCover). Свежие файлы не трогает: они могут
    /// принадлежать сохранению, которое ещё идёт.
    @concurrent
    func removeOrphans(keeping usedIDs: Set<UUID>) async {
        let fileManager = FileManager.default
        guard let files = try? fileManager.contentsOfDirectory(
            at: directory, includingPropertiesForKeys: [.creationDateKey]
        ) else { return }

        let cutoff = Date.now.addingTimeInterval(-3600)
        for url in files {
            guard let id = UUID(uuidString: String(url.lastPathComponent.prefix(36))),
                  !usedIDs.contains(id) else { continue }
            let created = (try? url.resourceValues(forKeys: [.creationDateKey]).creationDate) ?? .distantPast
            if created < cutoff {
                try? fileManager.removeItem(at: url)
            }
        }
    }

    // MARK: Внутреннее

    private func fileURL(_ id: UUID, _ rendition: CoverRendition) -> URL {
        directory.appending(path: "\(id.uuidString)-\(rendition.fileSuffix)", directoryHint: .notDirectory)
    }

    private func cacheKey(_ id: UUID, _ rendition: CoverRendition) -> String {
        "\(id.uuidString)-\(rendition.fileSuffix)"
    }

    private func removeFiles(_ id: UUID) {
        for rendition in CoverRendition.allCases {
            try? FileManager.default.removeItem(at: fileURL(id, rendition))
            cache.remove(forKey: cacheKey(id, rendition))
        }
    }

    /// Уменьшает картинку и поворачивает «как на экране» (фото с камеры хранит поворот отдельно).
    private static func render(_ image: UIImage, maxPixelSize: Int) throws -> CGImage {
        let pixelWidth = image.size.width * image.scale
        let pixelHeight = image.size.height * image.scale
        let scale = min(1, CGFloat(maxPixelSize) / max(pixelWidth, pixelHeight))
        let target = CGSize(width: (pixelWidth * scale).rounded(), height: (pixelHeight * scale).rounded())

        let format = UIGraphicsImageRendererFormat()
        format.scale = 1
        format.opaque = true
        format.preferredRange = .standard
        let rendered = UIGraphicsImageRenderer(size: target, format: format).image { _ in
            image.draw(in: CGRect(origin: .zero, size: target))
        }
        guard let cgImage = rendered.cgImage else { throw CoverError.renderFailed }
        return cgImage
    }

    /// HEIC примерно вдвое меньше JPEG; JPEG — запасной вариант.
    private static func encode(_ image: CGImage) throws -> Data {
        for type in [UTType.heic, UTType.jpeg] {
            let data = NSMutableData()
            guard let destination = CGImageDestinationCreateWithData(
                data as CFMutableData, type.identifier as CFString, 1, nil
            ) else { continue }
            let options = [kCGImageDestinationLossyCompressionQuality: 0.75] as CFDictionary
            CGImageDestinationAddImage(destination, image, options)
            if CGImageDestinationFinalize(destination) {
                return data as Data
            }
        }
        throw CoverError.encodingFailed
    }
}

/// Кэш готовых к показу картинок с лимитом памяти; при нехватке памяти система чистит его сама.
nonisolated final class CoverCache: @unchecked Sendable {
    // NSCache потокобезопасен, поэтому @unchecked Sendable здесь корректен.
    private let storage = NSCache<NSString, UIImage>()

    init() {
        storage.totalCostLimit = 50 * 1024 * 1024
    }

    func image(forKey key: String) -> UIImage? {
        storage.object(forKey: key as NSString)
    }

    func insert(_ image: UIImage, forKey key: String, cost: Int) {
        storage.setObject(image, forKey: key as NSString, cost: cost)
    }

    func remove(forKey key: String) {
        storage.removeObject(forKey: key as NSString)
    }
}
```

### 3. `BookCoverView.swift`: обложка с заглушкой

```swift
import SwiftUI

/// Обложка книги, заполняет отведённую рамку. Без обложки — нейтральная заглушка.
struct BookCoverView: View {
    let coverID: UUID?
    let rendition: CoverRendition

    @State private var image: UIImage?

    init(coverID: UUID?, rendition: CoverRendition) {
        self.coverID = coverID
        self.rendition = rendition
        // Уже загруженная обложка видна с первого кадра, без мигания при прокрутке.
        // На экране книги, пока грузится крупная версия, показываем маленькую.
        let store = CoverStore.shared
        _image = State(initialValue: coverID.flatMap {
            store.cachedImage($0, rendition) ?? store.cachedImage($0, .thumbnail)
        })
    }

    var body: some View {
        Rectangle()
            .fill(.quaternary)
            .overlay {
                if let image {
                    Image(uiImage: image)
                        .resizable()
                        .scaledToFill()
                } else {
                    Image(systemName: "book.closed")
                        .foregroundStyle(.secondary)
                }
            }
            .clipShape(RoundedRectangle(cornerRadius: 4))
            // Название книги и так читается VoiceOver; обложка — оформление.
            .accessibilityHidden(true)
            .task(id: coverID) {
                guard let coverID else {
                    image = nil
                    return
                }
                let loaded = await CoverStore.shared.loadImage(coverID, rendition)
                if !Task.isCancelled {
                    image = loaded
                }
            }
    }
}
```

### 4. `CameraPicker.swift`: камера

```swift
import SwiftUI
import UIKit

/// Системная камера. Без камеры (симулятор) открывает галерею.
struct CameraPicker: UIViewControllerRepresentable {
    let onCapture: (UIImage) -> Void
    @Environment(\.dismiss) private var dismiss

    func makeUIViewController(context: Context) -> UIImagePickerController {
        let picker = UIImagePickerController()
        picker.sourceType = UIImagePickerController.isSourceTypeAvailable(.camera) ? .camera : .photoLibrary
        picker.delegate = context.coordinator
        return picker
    }

    func updateUIViewController(_ picker: UIImagePickerController, context: Context) {
        context.coordinator.parent = self
    }

    func makeCoordinator() -> Coordinator {
        Coordinator(parent: self)
    }

    @MainActor
    final class Coordinator: NSObject, UIImagePickerControllerDelegate, UINavigationControllerDelegate {
        var parent: CameraPicker

        init(parent: CameraPicker) {
            self.parent = parent
        }

        func imagePickerController(
            _ picker: UIImagePickerController,
            didFinishPickingMediaWithInfo info: [UIImagePickerController.InfoKey: Any]
        ) {
            if let image = info[.originalImage] as? UIImage {
                parent.onCapture(image)
            }
            parent.dismiss()
        }

        func imagePickerControllerDidCancel(_ picker: UIImagePickerController) {
            parent.dismiss()
        }
    }
}
