### 5. `BookDetailView.swift`: экран книги

```swift
import SwiftUI
import SwiftData

struct BookDetailView: View {
    let book: Book

    @Environment(\.modelContext) private var modelContext
    @State private var isShowingCamera = false
    @State private var isSavingCover = false
    @State private var isShowingSaveError = false
    @State private var isConfirmingRemoval = false

    var body: some View {
        ScrollView {
            VStack(spacing: 16) {
                BookCoverView(coverID: book.coverID, rendition: .full)
                    .frame(width: 200, height: 300)
                    .overlay {
                        if isSavingCover {
                            ProgressView()
                        }
                    }
                    .shadow(radius: 6, y: 3)

                VStack(spacing: 4) {
                    Text(book.title)
                        .font(.title2.bold())
                        .multilineTextAlignment(.center)
                    Text(book.author)
                        .foregroundStyle(.secondary)
                }

                Button(
                    book.coverID == nil ? "Сфотографировать обложку" : "Переснять обложку",
                    systemImage: "camera"
                ) {
                    isShowingCamera = true
                }
                .buttonStyle(.bordered)
                .disabled(isSavingCover)

                if book.coverID != nil {
                    Button("Удалить обложку", role: .destructive) {
                        isConfirmingRemoval = true
                    }
                    .disabled(isSavingCover)
                }
            }
            .padding()
            .frame(maxWidth: .infinity)
        }
        .fullScreenCover(isPresented: $isShowingCamera) {
            CameraPicker { photo in
                setCover(photo)
            }
            .ignoresSafeArea()
        }
        .alert("Не удалось сохранить обложку", isPresented: $isShowingSaveError) {
            Button("OK", role: .cancel) {}
        } message: {
            Text("Попробуйте ещё раз. Если не поможет, проверьте, есть ли свободное место на iPhone.")
        }
        .confirmationDialog("Удалить обложку?", isPresented: $isConfirmingRemoval, titleVisibility: .visible) {
            Button("Удалить", role: .destructive) {
                removeCover()
            }
        }
    }

    /// Порядок важен: новые файлы → ссылка в книге → удаление старых файлов.
    /// Обычный Task, а не .task: сохранение доводится до конца, даже если экран закрыли.
    private func setCover(_ photo: UIImage) {
        isSavingCover = true
        Task {
            defer { isSavingCover = false }
            do {
                let newID = try await CoverStore.shared.saveCover(from: photo)
                let oldID = book.coverID
                book.coverID = newID
                try modelContext.save()
                if let oldID {
                    await CoverStore.shared.deleteCover(oldID)
                }
            } catch {
                isShowingSaveError = true
            }
        }
    }

    private func removeCover() {
        guard let oldID = book.coverID else { return }
        book.coverID = nil
        try? modelContext.save()
        Task { await CoverStore.shared.deleteCover(oldID) }
    }
}
```

### 6. `LibraryView.swift`: список и очистка при запуске

```swift
import SwiftUI
import SwiftData

struct LibraryView: View {
    @Query(sort: \Book.addedAt, order: .reverse) private var books: [Book]
    @Environment(\.modelContext) private var modelContext

    var body: some View {
        NavigationStack {
            List {
                ForEach(books) { book in
                    NavigationLink(value: book) {
                        BookRow(book: book)
                    }
                }
                .onDelete { offsets in
                    for index in offsets {
                        books[index].deleteWithCover(from: modelContext)
                    }
                }
            }
            .navigationTitle("Библиотека")
            .navigationDestination(for: Book.self) { book in
                BookDetailView(book: book)
            }
        }
    }
}

struct BookRow: View {
    let book: Book

    var body: some View {
        HStack(spacing: 12) {
            BookCoverView(coverID: book.coverID, rendition: .thumbnail)
                .frame(width: 44, height: 66)
            VStack(alignment: .leading, spacing: 2) {
                Text(book.title)
                    .font(.headline)
                Text(book.author)
                    .font(.subheadline)
                    .foregroundStyle(.secondary)
            }
        }
    }
}

/// Один раз при запуске удаляет файлы обложек, на которые не ссылается ни одна книга.
struct OrphanCoverCleanup: ViewModifier {
    @Environment(\.modelContext) private var modelContext

    func body(content: Content) -> some View {
        content.task {
            var descriptor = FetchDescriptor<Book>(predicate: #Predicate { $0.coverID != nil })
            descriptor.propertiesToFetch = [\.coverID]
            // Если базу прочитать не удалось, ничего не удаляем.
            guard let books = try? modelContext.fetch(descriptor) else { return }
            await CoverStore.shared.removeOrphans(keeping: Set(books.compactMap(\.coverID)))
        }
    }
}

extension View {
    func removingOrphanCovers() -> some View {
        modifier(OrphanCoverCleanup())
    }
}
