### CoverImageProcessor.swift
```swift
import ImageIO
import UIKit

nonisolated struct ProcessedCover: Sendable {
    let imageData: Data
    let thumbnailData: Data
}

/// Тяжёлая работа с картинками вне главного потока, чтобы интерфейс не замирал.
nonisolated enum CoverImageProcessor {
    private static let imageMaxPixels: CGFloat = 1600
    private static let thumbnailMaxPixels: CGFloat = 300

    /// Фото с камеры: уменьшаем, выравниваем поворот, сжимаем.
    @concurrent static func process(_ photo: UIImage) async -> ProcessedCover? {
        encode(resized(photo, maxPixels: imageMaxPixels))
    }

    /// Фото из галереи: ImageIO сразу читает уменьшенную версию, не распаковывая оригинал целиком.
    @concurrent static func process(_ data: Data) async -> ProcessedCover? {
        let options: [CFString: Any] = [
            kCGImageSourceCreateThumbnailFromImageAlways: true,
            kCGImageSourceCreateThumbnailWithTransform: true,
            kCGImageSourceShouldCacheImmediately: true,
            kCGImageSourceThumbnailMaxPixelSize: Int(imageMaxPixels),
        ]
        guard let source = CGImageSourceCreateWithData(data as CFData, nil),
              let cgImage = CGImageSourceCreateThumbnailAtIndex(source, 0, options as CFDictionary)
        else { return nil }
        return encode(resized(UIImage(cgImage: cgImage), maxPixels: imageMaxPixels))
    }

    /// Распаковка JPEG/HEIC для показа, тоже не на главном потоке.
    @concurrent static func decode(_ data: Data) async -> UIImage? {
        UIImage(data: data)?.preparingForDisplay()
    }

    private static func encode(_ image: UIImage) -> ProcessedCover? {
        let thumbnail = resized(image, maxPixels: thumbnailMaxPixels)
        guard let imageData = image.heicData() ?? image.jpegData(compressionQuality: 0.8),
              let thumbnailData = thumbnail.jpegData(compressionQuality: 0.75)
        else { return nil }
        return ProcessedCover(imageData: imageData, thumbnailData: thumbnailData)
    }

    /// Перерисовка в нужный размер: учитывает поворот фото и отбрасывает метаданные, включая геопозицию.
    private static func resized(_ image: UIImage, maxPixels: CGFloat) -> UIImage {
        let width = image.size.width * image.scale
        let height = image.size.height * image.scale
        let factor = min(1, maxPixels / max(width, height))
        let size = CGSize(width: (width * factor).rounded(), height: (height * factor).rounded())
        let format = UIGraphicsImageRendererFormat()
        format.scale = 1
        format.opaque = true
        format.preferredRange = .standard
        return UIGraphicsImageRenderer(size: size, format: format).image { _ in
            image.draw(in: CGRect(origin: .zero, size: size))
        }
    }
}
```

### CoverThumbnailCache.swift
```swift
import UIKit

/// Уже распакованные миниатюры, чтобы при прокрутке не декодировать их заново.
/// NSCache сам освобождает память, когда системе её не хватает.
@MainActor
final class CoverThumbnailCache {
    static let shared = CoverThumbnailCache()
    private let cache = NSCache<NSUUID, UIImage>()

    private init() {
        cache.totalCostLimit = 40 * 1024 * 1024
    }

    func image(for id: UUID) -> UIImage? {
        cache.object(forKey: id as NSUUID)
    }

    func insert(_ image: UIImage, for id: UUID) {
        let bytes = Int(image.size.width * image.scale * image.size.height * image.scale) * 4
        cache.setObject(image, forKey: id as NSUUID, cost: bytes)
    }
}
