### BookCoverStore.swift
```swift
import SwiftData

@MainActor
enum BookCoverStore {
    static func setCover(_ processed: ProcessedCover, for book: Book, in context: ModelContext) throws {
        let old = book.cover
        let cover = BookCover(thumbnailData: processed.thumbnailData)
        let image = BookCoverImage(data: processed.imageData)
        context.insert(cover)
        context.insert(image)
        cover.image = image
        book.cover = cover
        if let old { context.delete(old) }
        try context.save()
    }

    static func removeCover(from book: Book, in context: ModelContext) throws {
        guard let old = book.cover else { return }
        book.cover = nil
        context.delete(old)
        try context.save()
    }
}
