/// Маленькая обложка для строки списка.
struct BookCoverThumbnail: View {
    let cover: BookCover?
    @State private var loaded: LoadedCover?

    var body: some View {
        ZStack {
            CoverPlaceholder()
            if let image = currentImage {
                Image(uiImage: image)
                    .resizable()
                    .scaledToFill()
            }
        }
        .frame(width: 44, height: 66)
        .clipShape(.rect(cornerRadius: 4))
        .accessibilityHidden(true)
        .task(id: cover?.id) { await load() }
    }

    private var currentImage: UIImage? {
        guard let cover else { return nil }
        if let loaded, loaded.id == cover.id { return loaded.image }
        return CoverThumbnailCache.shared.image(for: cover.id)
    }

    private func load() async {
        guard let cover else { return }
        let id = cover.id
        if let cached = CoverThumbnailCache.shared.image(for: id) {
            loaded = LoadedCover(id: id, image: cached)
            return
        }
        let data = cover.thumbnailData
        guard let image = await CoverImageProcessor.decode(data), !Task.isCancelled else { return }
        CoverThumbnailCache.shared.insert(image, for: id)
        loaded = LoadedCover(id: id, image: image)
    }
}

/// Большая обложка для экрана книги: сразу показывает миниатюру из кэша, потом чёткую версию.
struct BookCoverImage: View {
    let cover: BookCover?
    let title: String
    @State private var loaded: LoadedCover?

    var body: some View {
        Group {
            if let image = currentImage {
                Image(uiImage: image)
                    .resizable()
                    .scaledToFit()
                    .accessibilityLabel("Обложка книги «\(title)»")
            } else {
                CoverPlaceholder(iconFont: .largeTitle)
                    .aspectRatio(2 / 3, contentMode: .fit)
                    .accessibilityHidden(true)
            }
        }
        .frame(maxWidth: 240, maxHeight: 360)
        .clipShape(.rect(cornerRadius: 8))
        .task(id: cover?.id) { await load() }
    }

    private var currentImage: UIImage? {
        guard let cover else { return nil }
        if let loaded, loaded.id == cover.id { return loaded.image }
        return CoverThumbnailCache.shared.image(for: cover.id)
    }

    private func load() async {
        guard let cover, let data = cover.image?.data else { return }
        let id = cover.id
        guard let image = await CoverImageProcessor.decode(data), !Task.isCancelled else { return }
        loaded = LoadedCover(id: id, image: image)
    }
}
