```swift
import AVFoundation
import PhotosUI
import SwiftData
import SwiftUI

/// Кнопка «Добавить / Изменить обложку»: камера, галерея, удаление.
struct CoverMenu: View {
    let book: Book

    @Environment(\.modelContext) private var modelContext
    @Environment(\.openURL) private var openURL
    @State private var isShowingCamera = false
    @State private var isShowingLibrary = false
    @State private var libraryItem: PhotosPickerItem?
    @State private var isProcessing = false
    @State private var isShowingCameraDenied = false
    @State private var isConfirmingRemoval = false
    @State private var isShowingError = false

    var body: some View {
        Menu {
            if UIImagePickerController.isSourceTypeAvailable(.camera) {
                Button("Сфотографировать", systemImage: "camera") {
                    Task { await openCamera() }
                }
            }
            Button("Выбрать из фото", systemImage: "photo.on.rectangle") {
                isShowingLibrary = true
            }
            if book.cover != nil {
                Button("Удалить обложку", systemImage: "trash", role: .destructive) {
                    isConfirmingRemoval = true
                }
            }
        } label: {
            if isProcessing {
                ProgressView()
                    .accessibilityLabel("Обложка сохраняется")
            } else {
                Label(book.cover == nil ? "Добавить обложку" : "Изменить обложку", systemImage: "camera")
            }
        }
        .disabled(isProcessing)
        .fullScreenCover(isPresented: $isShowingCamera) {
            CameraPicker { photo in
                isShowingCamera = false
                if let photo {
                    Task { await importFromCamera(photo) }
                }
            }
            .ignoresSafeArea()
        }
        .photosPicker(isPresented: $isShowingLibrary, selection: $libraryItem, matching: .images)
        .onChange(of: libraryItem) { _, item in
            guard let item else { return }
            libraryItem = nil
            Task { await importFromLibrary(item) }
        }
        .confirmationDialog("Удалить обложку?", isPresented: $isConfirmingRemoval, titleVisibility: .visible) {
            Button("Удалить", role: .destructive) { removeCover() }
        }
        .alert("Нет доступа к камере", isPresented: $isShowingCameraDenied) {
            Button("Открыть настройки") {
                if let url = URL(string: UIApplication.openSettingsURLString) { openURL(url) }
            }
            Button("Отмена", role: .cancel) {}
        } message: {
            Text("Разрешите доступ к камере в Настройках, чтобы фотографировать обложки.")
        }
        .alert("Не удалось сохранить обложку", isPresented: $isShowingError) {
            Button("OK", role: .cancel) {}
        } message: {
            Text("Попробуйте ещё раз.")
        }
    }

    private func openCamera() async {
        switch AVCaptureDevice.authorizationStatus(for: .video) {
        case .authorized:
            isShowingCamera = true
        case .notDetermined:
            if await AVCaptureDevice.requestAccess(for: .video) {
                isShowingCamera = true
            } else {
                isShowingCameraDenied = true
            }
        default:
            isShowingCameraDenied = true
        }
    }

    private func importFromCamera(_ photo: UIImage) async {
        isProcessing = true
        defer { isProcessing = false }
        guard let processed = await CoverImageProcessor.process(photo) else {
            isShowingError = true
            return
        }
        apply(processed)
    }

    private func importFromLibrary(_ item: PhotosPickerItem) async {
        isProcessing = true
        defer { isProcessing = false }
        do {
            guard let data = try await item.loadTransferable(type: Data.self),
                  let processed = await CoverImageProcessor.process(data)
            else {
                isShowingError = true
                return
            }
            apply(processed)
        } catch {
            isShowingError = true
        }
    }

    private func apply(_ processed: ProcessedCover) {
        // Книгу могли удалить, пока фото обрабатывалось.
        guard !book.isDeleted, book.modelContext != nil else { return }
        do {
            try BookCoverStore.setCover(processed, for: book, in: modelContext)
        } catch {
            isShowingError = true
        }
    }

    private func removeCover() {
        do {
            try BookCoverStore.removeCover(from: book, in: modelContext)
        } catch {
            isShowingError = true
        }
    }
}
